    std::vector<std::vector<int>> seePeople(std::vector<std::vector<int>>& heights) {
        int m = heights.size(), n = heights[0].size();
        std::vector<std::vector<int>> ans(m, std::vector<int>(n, 0));
        for (int r = 0; r < m; ++r) {
            std::vector<int> stk;
            for (int c = n - 1; c >= 0; --c) {
                int cnt = 0;
                while (!stk.empty() && heights[r][c] > stk.back()) {
                    stk.pop_back();
                    cnt++;
