class Solution {
    public int[][] seePeople(int[][] heights) {
        int m = heights.length, n = heights[0].length;
        int[][] ans = new int[m][n];
        int[] stk = new int[Math.max(m, n)];
        for (int r = 0; r < m; r++) {
            int top = -1;
            for (int c = n - 1; c >= 0; c--) {
                int cnt = 0;
                while (top >= 0 && heights[r][c] > stk[top]) {
                    top--;
                    cnt++;
                }
                if (top >= 0) {
                    cnt++;
                    if (stk[top] == heights[r][c]) top--;
                }
                stk[++top] = heights[r][c];
                ans[r][c] += cnt;
            }
        }
        for (int c = 0; c < n; c++) {
            int top = -1;
            for (int r = m - 1; r >= 0; r--) {
                int cnt = 0;
                while (top >= 0 && heights[r][c] > stk[top]) {
                    top--;
                    cnt++;
                }
                if (top >= 0) {
                    cnt++;
                    if (stk[top] == heights[r][c]) top--;
                }
                stk[++top] = heights[r][c];
                ans[r][c] += cnt;
            }
        }
        return ans;
    }
}

